  },
  studio_location: "TO_VALIDATE_STUDIO_LOCATION",
  deposit_policy: "TO_VALIDATE_DEPOSIT_POLICY",
  cancellation_policy: "TO_VALIDATE_CANCELLATION_POLICY",
  owner_notification_email: "TO_VALIDATE_OWNER_EMAIL",
  reminder_escalation_hours: 48,
  reminder_resend_cooldown_hours: 20,
  templates: {
    deposit_request_template: "TEMPORARY — OWNER WORDING TO VALIDATE\n\nHi {{customer_name}}! Your appointment for {{service}} on {{booking_date}} at {{booking_time}} has been received.\nA deposit of Rs {{deposit_amount}} via {{payment_method}} is required to secure your booking.\n{{payment_method}} payment details: {{juice_payment_details}}\nOnce you've made the payment, please send your payment screenshot here.\nYour booking will only be confirmed after the payment has been manually verified.",
    deposit_reminder_template: "TEMPORARY — OWNER WORDING TO VALIDATE\n\nHi {{customer_name}}, just a reminder that the Rs {{deposit_amount}} {{payment_method}} deposit for your appointment on {{booking_date}} at {{booking_time}} is still pending.\nPayment details:\n{{juice_payment_details}}\nPlease send your payment screenshot after payment so the booking can be verified.",
    booking_confirmation_template: "TEMPORARY — OWNER WORDING TO VALIDATE\n\nHi {{customer_name}}, your Rs {{deposit_amount}} deposit has been manually verified and your booking is now confirmed for {{booking_date}} at {{booking_time}}.\nLocation:\n{{studio_location}}\nBooking/deposit policy:\n{{deposit_policy}}\nSee you soon!"
  }
};

return $input.all().map(item => ({ json: { ...item.json, config } }));

// Real Fresha email parser, built from 3 genuine Fresha email samples analysed
// 25 Aug 2026 (see docs/mehua-deposit-concierge-spec.md, "Real Fresha email
// analysis"). Two structurally different Fresha email types were found:
//   - Format A "New appointment" (owner-facing, plain-text-style) - the ONLY
//     type this workflow should act on. Has customer contact details but NO
//     Fresha booking reference.
//   - Format B (client-facing HTML cards: cancellation notice, "complete
//     form" reminder) - has a stable "Booking ref:" but is NOT a new-booking
//     trigger and must never be parsed into a new deposit record.
// Classifies the email kind FIRST. Only "new_booking" extracts full booking
// fields. Everything else (recognized-but-out-of-scope Format B emails, or
// truly unknown input) routes to NEEDS_HUMAN_REVIEW with a distinct reason -
// never silently dropped, never guessed into a booking.
const item = $input.item.json;
const config = item.config;
const subject = item.subject || '';
const body = item.text || item.html || '';

const MONTHS = {
  jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06',
  jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12'
};

function normalizePhone(raw) {
  if (!raw) return null;
  const digits = raw.replace(/\D/g, '');
  return digits || null;
}

function extractFreshaBookingRef(text) {
  // Present in Format B ("Booking ref: EC174CE2"), confirmed absent in
  // Format A across all 3 real samples. Extracted here regardless of
  // classification so it is never silently missed if Fresha's format
  // ever changes - see spec's idempotency-key note.
  const m = text.match(/Booking ref:\s*([A-Za-z0-9]{6,10})/i);
  return m ? m[1].trim().toUpperCase() : null;
}

function parseDateTimeLine(line) {
  // Format A shape: "Wednesday, 9 Sep 2026, 10:00"
  const m = line.match(/^\s*\w+,\s*(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4}),\s*(\d{1,2}:\d{2})\s*$/);
  if (!m) return null;
  const [, day, monName, year, time] = m;
  const mon = MONTHS[monName.slice(0, 3).toLowerCase()];
  if (!mon) return null;
  return { date: `${year}-${mon}-${day.padStart(2, '0')}`, time };
}

function classify(subjectText, bodyText) {
  const bookedOnline = /has been booked online/i.test(bodyText);
  const cancelled = /has been cancelled/i.test(subjectText) || /appointment has been cancelled/i.test(bodyText);
  const actionRequired = /Action required/i.test(bodyText) && /Complete form/i.test(bodyText);
  if (bookedOnline) return 'new_booking';
  if (cancelled) return 'recognized_other:cancellation';
  if (actionRequired) return 'recognized_other:action_required_form';
  return 'unknown';
}

function extractNewBookingFields(bodyText) {
  const errors = [];

  const bookedMatch = bodyText.match(/has been booked online\s*\r?\n+([^\r\n]+)\r?\n([^\r\n]+)/i);
  let service = null, staffName = null, bookingDate = null, bookingTime = null;
  if (bookedMatch) {
    const serviceStaffLine = bookedMatch[1].trim();
    const dateTimeLine = bookedMatch[2].trim();
    const ssMatch = serviceStaffLine.match(/^(.*?)\s+with\s+(.+)$/i);
    if (ssMatch) {
      service = ssMatch[1].trim();
      staffName = ssMatch[2].trim();
    } else if (serviceStaffLine) {
      service = serviceStaffLine;
    }
    const dt = parseDateTimeLine(dateTimeLine);
    if (dt) {
      bookingDate = dt.date;
      bookingTime = dt.time;
    }
  }
  if (!service) errors.push('service not found');
  if (!bookingDate || !bookingTime) errors.push('appointment date/time not found or unparseable');

  let customerName = null, customerEmail = null, customerPhone = null;
  const custMatch = bodyText.match(/Customer details:\s*\r?\n+([\s\S]{0,300})/i);
  if (custMatch) {
    const lines = custMatch[1].split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
    for (const line of lines.slice(0, 4)) {
      if (/^Powered by Fresha/i.test(line)) break;
      if (line.includes('@')) { customerEmail = line; continue; }
      if (/^\+?[\d ()-]{7,}$/.test(line)) { customerPhone = line; continue; }
      if (!customerName) { customerName = line; continue; }
    }
  }
  if (!customerName) errors.push('customer name not found');

  return { service, staffName, bookingDate, bookingTime, customerName, customerEmail, customerPhone, errors };
}

function makeBookingReference() {
  // Human-typeable reference the owner enters into the two owner-facing
  // forms later (report proof / review verification). Distinct from the
  // idempotency key below, which is never shown to or typed by the owner.
  const now = new Date();
  const yymmdd = now.toISOString().slice(2, 10).replace(/-/g, '');
  const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
  return `MH-${yymmdd}-${rand}`;
}

const emailKind = classify(subject, body);
const freshaBookingRef = extractFreshaBookingRef(body);

let result;

if (emailKind === 'new_booking') {
  const parsed = extractNewBookingFields(body);
  const requiredOk = Boolean(parsed.service && parsed.bookingDate && parsed.bookingTime && parsed.customerName);

  let contactMatchStrength = null;
  let contactKey = null;
  if (parsed.customerEmail) {
    contactMatchStrength = 'email';
    contactKey = parsed.customerEmail.trim().toLowerCase();
  } else if (parsed.customerPhone) {
    contactMatchStrength = 'phone';
    contactKey = normalizePhone(parsed.customerPhone);
  } else if (parsed.customerName) {
    contactMatchStrength = 'name_only';
    contactKey = parsed.customerName.trim().toLowerCase();
  }

  const compositeKey = requiredOk
    ? [contactKey, parsed.bookingDate, parsed.bookingTime, parsed.service.trim().toLowerCase()].join('|')
    : null;

  result = {
    config,
    emailKind,
    parseOk: requiredOk,
    requiresHumanReview: !requiredOk,
    reviewReason: requiredOk ? null : `new_booking email missing required field(s): ${parsed.errors.join(', ')}`,
    bookingReference: requiredOk ? makeBookingReference() : null,
    clientName: parsed.customerName,
    service: parsed.service,
    staffName: parsed.staffName,
    bookingDate: parsed.bookingDate,
    bookingTime: parsed.bookingTime,
    customerEmail: parsed.customerEmail,
    customerPhone: parsed.customerPhone,
    freshaBookingRef,
    contactMatchStrength,
    compositeKey,
    idempotencyKey: freshaBookingRef || compositeKey,
    isRecognizedNonBooking: false,
    subject,
    source: 'email'
  };
} else {
  const reasonMap = {
    'recognized_other:cancellation': 'Recognized Fresha cancellation email - out of scope for Phase 1 (no booking created or modified).',
    'recognized_other:action_required_form': 'Recognized Fresha "complete form" reminder email - out of scope for Phase 1 (no booking created or modified).',
    unknown: 'Unrecognized email format - could not classify as a Fresha new-booking notification.'
  };
  const isRecognizedNonBooking = emailKind.startsWith('recognized_other:');
  result = {
    config,
    emailKind,
    parseOk: false,
    // A recognized Format B email (cancellation / complete-form reminder) is
    // expected, out-of-scope-for-Phase-1 input - NOT an error a human needs
    // to review. Only a truly unrecognized email format sets this true.
    requiresHumanReview: emailKind === 'unknown',
    isRecognizedNonBooking,
    reviewReason: reasonMap[emailKind] || reasonMap.unknown,
    bookingReference: null,
    clientName: null,
    service: null,
    staffName: null,
    bookingDate: null,
    bookingTime: null,
    customerEmail: null,
    customerPhone: null,
    freshaBookingRef,
    contactMatchStrength: null,
    compositeKey: null,
    idempotencyKey: null,
    subject,
    source: 'email'
  };
}

return [{ json: result }];

