// The Google Sheets read above replaced $input with sheet rows, so the just-parsed booking is fetched back by node name rather than $input.
const current = $('Parsed OK?').first().json;
const rows = $input.all().map((i) => i.json);
const currentKey = current.idempotencyKey;

const match = rows.find(
  (r) => currentKey && r['Idempotency Key'] && r['Idempotency Key'] === currentKey
);

return [{
  json: {
    ...current,
    isDuplicate: Boolean(match),
    duplicateOfBookingReference: match ? match['Booking Reference'] : null
  }
}];

// Terminal node - intentionally does NOT write to the Booking Log. Not writing a new row IS the correct behavior for a duplicate: no second booking record, no second deposit draft, no second reminder lifecycle. n8n's own execution log makes this branch observable (event: 'duplicate_booking_ignored') without touching the sheet.
const item = $input.item.json;
return [{
  json: {
    event: 'duplicate_booking_ignored',
    idempotencyKey: item.idempotencyKey,
    duplicateOfBookingReference: item.duplicateOfBookingReference,
    subject: item.subject
  }
}];

